<?php
function movie_form(?int $id): void {global $db;$m=$id?movie($id):[];$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf();foreach(['Movie_name','Genre','Price','Date_of_release'] as $k)$m[$k]=input($_POST,$k);$d=DateTimeImmutable::createFromFormat('!Y-m-d',$m['Date_of_release']);if($m['Movie_name']===''||mb_strlen($m['Movie_name'])>100||$m['Genre']===''||mb_strlen($m['Genre'])>20)$error='Enter a title and genre within the length limits.';elseif(!preg_match('/^\d{1,7}(\.\d{1,2})?$/D',$m['Price']))$error='Enter a valid non-negative price.';elseif(!$d||$d->format('Y-m-d')!==$m['Date_of_release']||$d->format('Y')<'1000')$error='Enter a valid release date.';else{$p=[$m['Movie_name'],$m['Genre'],$m['Price'],$m['Date_of_release']];if($id){$p[]=$id;$s=$db->prepare('UPDATE movies SET Movie_name=?,Genre=?,Price=?,Date_of_release=? WHERE Movie_id=?');}else{$s=$db->prepare('INSERT INTO movies (Movie_name,Genre,Price,Date_of_release) VALUES (?,?,?,?)');}$s->execute($p);go('list-movies.php');}}render('form.twig',['movie'=>$m,'editing'=>$id!==null,'error'=>$error]);}
